"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a slider. Pass `value` to control it, or `defaultValue` to let it hold its own state. */
export interface SliderProps {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Names the slider for screen readers and shows as its visible label. */
  label: ReactNode;
  /** Formats the value shown beside the label and read out as `aria-valuetext`. */
  formatValue?: (value: number) => string;
  disabled?: boolean;
  className?: string;
}

// While the pointer drags, the fill follows it with no lag: direct
// manipulation must stay under the finger. Keyboard steps get a short,
// critically damped spring so each step is visible.
const FOLLOW: Transition = { duration: 0 };
const STEP_SPRING: Transition = { type: "spring", stiffness: 700, damping: 53, mass: 1 };
const THUMB_SPRING: Transition = { type: "spring", stiffness: 500, damping: 30, mass: 1 };

/**
 * Picks a number in a range by dragging, clicking the track or pressing arrow
 * keys. A native range input does the work underneath, so every assistive
 * technology and keyboard shortcut still applies.
 */
export function Slider({
  value,
  defaultValue,
  onValueChange,
  min = 0,
  max = 100,
  step = 1,
  label,
  formatValue = String,
  disabled,
  className,
}: SliderProps) {
  const [ownValue, setOwnValue] = useState(defaultValue ?? min);
  const [dragging, setDragging] = useState(false);
  // One controller removes both window listeners, whichever event ends the drag.
  const dragEnd = useRef<AbortController | null>(null);
  useEffect(() => () => dragEnd.current?.abort(), []);
  const current = Math.min(max, Math.max(min, value ?? ownValue));
  const fraction = max > min ? (current - min) / (max - min) : 0;
  const reduceMotion = useReducedMotion();
  const text = formatValue(current);

  const move = reduceMotion || dragging ? FOLLOW : STEP_SPRING;

  return (
    <label className={cn("flex w-full flex-col gap-3 text-sm", disabled && "opacity-50", className)}>
      <span className="flex items-baseline justify-between gap-4">
        <span className="font-medium text-foreground">{label}</span>
        <span className="tabular-nums text-muted-foreground" aria-hidden="true">
          {text}
        </span>
      </span>
      <span className="relative flex h-11 items-center sm:h-6">
        <span className="relative h-1.5 w-full overflow-hidden rounded-full bg-muted-foreground/25">
          <motion.span
            aria-hidden="true"
            initial={false}
            animate={{ scaleX: fraction }}
            transition={move}
            className="absolute inset-0 origin-left rounded-full bg-primary"
          />
        </span>
        {/* The thumb rides a layer with no width that moves along the track. A full-width layer shifted by a share of
            its own width would reach past the track's end and let a clipping parent scroll sideways. */}
        <motion.span
          aria-hidden="true"
          initial={false}
          animate={{ left: `${fraction * 100}%` }}
          transition={move}
          className="pointer-events-none absolute left-0 flex w-0"
        >
          <motion.span
            animate={{ scale: dragging && !reduceMotion ? 1.15 : 1 }}
            transition={THUMB_SPRING}
            className="block size-5 -translate-x-1/2 rounded-full border border-border bg-background shadow-sm"
          />
        </motion.span>
        <input
          type="range"
          min={min}
          max={max}
          step={step}
          value={current}
          disabled={disabled}
          aria-valuetext={text}
          onChange={(event) => {
            const next = Number(event.target.value);
            if (value === undefined) setOwnValue(next);
            onValueChange?.(next);
          }}
          onPointerDown={() => {
            setDragging(true);
            // The pointer can leave the input before it lifts, so listen on the window.
            dragEnd.current?.abort();
            const controller = new AbortController();
            dragEnd.current = controller;
            const end = () => {
              setDragging(false);
              controller.abort();
            };
            window.addEventListener("pointerup", end, { signal: controller.signal });
            window.addEventListener("pointercancel", end, { signal: controller.signal });
          }}
          onBlur={() => setDragging(false)}
          className="peer absolute inset-0 h-full w-full cursor-pointer touch-pan-y appearance-none opacity-0 disabled:cursor-not-allowed [&::-moz-range-thumb]:size-0 [&::-webkit-slider-thumb]:size-0 [&::-webkit-slider-thumb]:appearance-none"
        />
        <span
          aria-hidden="true"
          className="pointer-events-none absolute inset-x-0 top-1/2 h-6 -translate-y-1/2 rounded-full peer-focus-visible:ring-2 peer-focus-visible:ring-ring peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-background"
        />
      </span>
    </label>
  );
}
